-- Core protocol controls used by indexer reconciliation. Defaults below are
-- the mapping's constructor values, and only apply before their update events.
CREATE VIEW graph_network AS
SELECT '1' AS id,
       '0x0a8491544221dd212964fbb96487467291b2c97e' AS controller,
       (SELECT governor FROM controller_state) AS governor,
       coalesce((SELECT "pauseGuardian" FROM controller_state), '0x0000000000000000000000000000000000000000') AS "pauseGuardian",
       coalesce((SELECT "contractAddress" FROM controller_contract WHERE id = '0x1df41cd916959d1163dc8f0671a666ea8a3e434c13e40faef527133b5d167034'), '0x00669a4cf01450b64e8a2a20e9b1fcb71e61ef03') AS "staking",
       coalesce((SELECT "contractAddress" FROM controller_contract WHERE id = '0xc713c3df6d14cdf946460395d09af88993ee2b948b1a808161494e32c5f67063'), '0x5a843145c43d328b9bb7a4401d94918f131bb281') AS "epochManager",
       coalesce((SELECT "contractAddress" FROM controller_contract WHERE id = '0x966f1e8d8d8014e05f6ec4a57138da9be1f7c5a7f802928a18072f7c53180761'), '0x971b9d3d0ae3eca029cab5ea1fb0f72c85e6a525') AS "rewardsManager",
       coalesce((SELECT "contractAddress" FROM controller_contract WHERE id = '0xe6876326c1291dfcbbd3864a6816d698cd591defc7aa2153d7f9c4c04016c89f'), '0x22d78fb4bc72e191c765807f8891b5e1785c8014') AS "curation",
       coalesce((SELECT "contractAddress" FROM controller_contract WHERE id = '0x39605a6c26a173774ca666c67ef70cf491880e5d3d6d0ca66ec0a31034f15ea3'), '0xec9a7fb6cbc2e41926127929c2dce6e9c5d33bec') AS "gns",
       coalesce((SELECT "contractAddress" FROM controller_contract WHERE id = '0xf942813d07d17b56de9a9afc8de0ced6e8c053bbfdcc87b7badea4ddcf27c307'), '0x2fe023a575449acb698648ed21276293fa176f96') AS "disputeManager",
       coalesce((SELECT "contractAddress" FROM controller_contract WHERE id = '0x45fc200c7e4544e457d3c5709bfe0d520442c30bbcbdaede89e8d4a4bbc19247'), '0x9623063377ad1b27544c965ccd7342f7ea7e88c7') AS "graphToken",
       CAST(coalesce((SELECT epoch FROM network_epoch_observation ORDER BY block_number DESC, log_index DESC LIMIT 1), 0) AS INTEGER) AS "currentEpoch",
       CAST(coalesce((SELECT length FROM epoch_schedule ORDER BY seq DESC LIMIT 1), 0) AS INTEGER) AS "epochLength",
       CAST(coalesce((SELECT epoch FROM epoch_manager__epoch_run ORDER BY block_number DESC, log_index DESC LIMIT 1), '0') AS INTEGER) AS "lastRunEpoch",
       CAST(coalesce((SELECT epoch FROM epoch_schedule ORDER BY seq DESC LIMIT 1), 0) AS INTEGER) AS "lastLengthUpdateEpoch",
       CAST(coalesce((SELECT start_block FROM epoch_schedule ORDER BY seq DESC LIMIT 1), 0) AS INTEGER) AS "lastLengthUpdateBlock",
       CAST((SELECT count(*) FROM epoch_bounds) AS INTEGER) AS "epochCount",
       CAST(coalesce((SELECT l1_block FROM network_persisted_l1_observation ORDER BY block_number DESC, log_index DESC LIMIT 1), 0) AS VARCHAR) AS "currentL1BlockNumber",
       CAST(coalesce((SELECT value FROM protocol_parameters WHERE parameter = 'curationPercentage'), '0') AS INTEGER) AS "curationPercentage",
       CAST(coalesce((SELECT value FROM protocol_parameters WHERE parameter = 'protocolFeePercentage'), '0') AS INTEGER) AS "protocolFeePercentage",
       CAST(coalesce((SELECT value FROM protocol_parameters WHERE parameter = 'delegationRatio'), '0') AS INTEGER) AS "delegationRatio",
       CAST(coalesce((SELECT value FROM protocol_parameters WHERE parameter = 'channelDisputeEpochs'), '0') AS INTEGER) AS "channelDisputeEpochs",
       CAST(coalesce((SELECT value FROM protocol_parameters WHERE parameter = 'maxAllocationEpochs'), '0') AS INTEGER) AS "maxAllocationEpochs",
       CAST(coalesce((SELECT value FROM protocol_parameters WHERE parameter = 'thawingPeriod'), '0') AS INTEGER) AS "thawingPeriod",
       CAST(coalesce((SELECT value FROM protocol_parameters WHERE parameter = 'delegationParametersCooldown'), '0') AS INTEGER) AS "delegationParametersCooldown",
       CAST(coalesce((SELECT value FROM protocol_parameters WHERE parameter = 'delegationUnbondingPeriod'), '0') AS INTEGER) AS "delegationUnbondingPeriod",
       CAST(coalesce((SELECT value FROM protocol_parameters WHERE parameter = 'delegationTaxPercentage'), '0') AS INTEGER) AS "delegationTaxPercentage",
       coalesce((SELECT value FROM protocol_parameters WHERE parameter = 'maxThawingPeriod'), '0') AS "maxThawingPeriod",
       coalesce((SELECT value FROM protocol_parameters WHERE parameter = 'minimumIndexerStake'), '0') AS "minimumIndexerStake",
       coalesce((SELECT "networkGRTIssuancePerBlock" FROM network_issuance), '0') AS "networkGRTIssuancePerBlock",
       coalesce((SELECT "isPaused" FROM controller_state), false) AS "isPaused",
       coalesce((SELECT "isPartialPaused" FROM controller_state), false) AS "isPartialPaused",
       EXISTS (SELECT 1 FROM horizon_staking__delegation_slashing_enabled) AS "delegationSlashingEnabled",
       supply."totalSupply", supply."totalGRTMinted", supply."totalGRTBurned",
       CAST(coalesce((SELECT sum(tokens) FROM indexer_stake_movement), CAST(0 AS BIGNUM)) AS VARCHAR) AS "totalTokensStaked",
       CAST(coalesce((SELECT sum(CAST("allocatedTokens" AS BIGNUM)) FROM allocation_lifecycle WHERE status = 'Active'), CAST(0 AS BIGNUM)) AS VARCHAR) AS "totalTokensAllocated"
FROM graph_token_supply supply
WHERE EXISTS (SELECT 1 FROM network_refresh_event);
